// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  ArrowLeftIcon,
  BoldIcon,
  CalendarClockIcon,
  CheckIcon,
  ChevronRightIcon,
  CodeIcon,
  CopyIcon,
  CopyPlusIcon,
  DownloadIcon,
  EllipsisVerticalIcon,
  EyeIcon,
  FileDownIcon,
  Heading2Icon,
  ItalicIcon,
  LinkIcon,
  ListChecksIcon,
  ListIcon,
  ListOrderedIcon,
  PaletteIcon,
  PencilIcon,
  PinIcon,
  PlusIcon,
  PrinterIcon,
  QuoteIcon,
  Redo2Icon,
  SaveIcon,
  SearchIcon,
  SlidersHorizontalIcon,
  StrikethroughIcon,
  Trash2Icon,
  UnderlineIcon,
  Undo2Icon,
  type LucideIcon,
} from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  COLORS,
  EXPORTS,
  FILE,
  HEADING,
  LIST,
  MARKDOWN,
  PICKED_COLOR,
  PICKED_EXPORT,
  POSITION,
  STATS,
  TASKS,
  TICKED,
  TITLE,
  TOOLBAR,
} from './script'

const ICONS: Record<Exclude<(typeof TOOLBAR)[number], '|'>, LucideIcon> = {
  undo: Undo2Icon,
  redo: Redo2Icon,
  bold: BoldIcon,
  italic: ItalicIcon,
  underline: UnderlineIcon,
  strike: StrikethroughIcon,
  heading: Heading2Icon,
  bullet: ListIcon,
  ordered: ListOrderedIcon,
  check: ListChecksIcon,
  quote: QuoteIcon,
  code: CodeIcon,
  link: LinkIcon,
  date: CalendarClockIcon,
  find: SearchIcon,
}

const MENU: { label: string; Icon: LucideIcon; hint?: string; d?: string }[] = [
  { label: 'Export as', Icon: FileDownIcon, d: 'export-as' },
  { label: 'Copy as text', Icon: CopyIcon },
  { label: 'Copy with formatting', Icon: CopyIcon },
  { label: 'Print', Icon: PrinterIcon, hint: 'Ctrl+P' },
  { label: 'Save now', Icon: SaveIcon, hint: 'Ctrl+S' },
  { label: 'Duplicate', Icon: CopyPlusIcon },
]

const pop = { opacity: 0, y: -4, scale: 0.97 }
const popIn = {
  opacity: 1,
  y: 0,
  scale: 1,
  duration: 0.2,
  ease: 'power2.out',
  immediateRender: false,
}

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  step(0)
  move('new', { at: 0.2 })
  click('new')
  tl.to(q('view-list'), { opacity: 0, x: -12, duration: 0.25 }, '<')
  tl.fromTo(
    q('view-editor'),
    { opacity: 0, x: 12 },
    { opacity: 1, x: 0, duration: 0.3, immediateRender: false },
    '<0.1',
  )
  type('title-text', TITLE, { speed: 0.035, at: '+=0.1' })
  tl.to(q('title-ph'), { opacity: 0, duration: 0.1 }, '<')
  tl.to(q('body-ph'), { opacity: 0, duration: 0.1 }, '+=0.1')
  type('l0-text', HEADING, { speed: 0.05, at: '<' })
  move('tb-heading', { at: '+=0.1' })
  click('tb-heading')
  tl.set(q('l0-pre'), { text: '## ' }, '<0.1')
  tl.to(q('l0'), { fontWeight: 600, duration: 0.1 }, '<')
  TASKS.forEach((task, index) => {
    tl.set(q(`l${index + 1}`), { opacity: 1 }, '+=0.05')
    type(`l${index + 1}-text`, task, { speed: 0.028 })
  })
  tl.fromTo(
    qa('sel'),
    { opacity: 0 },
    { opacity: 1, duration: 0.15, stagger: 0.05, immediateRender: false },
    '+=0.15',
  )
  move('tb-check')
  click('tb-check')
  TASKS.forEach((_, index) =>
    tl.set(q(`l${index + 1}-pre`), { text: '- [ ] ' }, index === 0 ? '<0.1' : '<'),
  )
  tl.to(qa('sel'), { opacity: 0, duration: 0.2 }, '<0.1')
  tl.to(q('status'), { opacity: 1, duration: 0.2 }, '<')

  step(1, '+=0.5')
  move('tb-preview')
  click('tb-preview')
  tl.to(q('tb-eye'), { opacity: 0, duration: 0.1 }, '<')
  tl.to(q('tb-pencil'), { opacity: 1, duration: 0.1 }, '<')
  tl.to(q('edit'), { opacity: 0, duration: 0.2 }, '<')
  tl.fromTo(
    q('preview'),
    { opacity: 0 },
    { opacity: 1, duration: 0.25, immediateRender: false },
    '<0.1',
  )
  move(`box-${TICKED}`, { at: '+=0.2' })
  click(`box-${TICKED}`)
  tl.to(q(`tick-${TICKED}`), { opacity: 1, scale: 1, duration: 0.15 }, '<')
  tl.to(
    q(`box-${TICKED}`),
    { backgroundColor: 'var(--accent)', borderColor: 'var(--accent)', duration: 0.15 },
    '<',
  )
  tl.to(
    q(`task-${TICKED}`),
    { opacity: 0.6, textDecorationColor: 'rgba(228,228,231,1)', duration: 0.2 },
    '<',
  )
  move('palette', { at: '+=0.3' })
  click('palette')
  tl.fromTo(q('colors'), pop, popIn, '<')
  move(`color-${PICKED_COLOR}`)
  click(`color-${PICKED_COLOR}`)
  tl.to(q(`color-check-${PICKED_COLOR}`), { opacity: 1, duration: 0.1 }, '<')
  tl.to(q('color-check-0'), { opacity: 0, duration: 0.1 }, '<')
  tl.to(q('colors'), { opacity: 0, duration: 0.2 }, '+=0.15')
  tl.to(
    q('surface'),
    {
      backgroundColor: 'rgba(251,191,36,0.1)',
      borderColor: 'rgba(251,191,36,0.3)',
      duration: 0.35,
    },
    '<',
  )

  step(2, '+=0.5')
  move('more')
  click('more')
  tl.fromTo(q('menu'), pop, popIn, '<')
  move('export-as')
  tl.to(q('export-as'), { backgroundColor: 'var(--demo-tint-8)', duration: 0.1 }, '<0.2')
  tl.fromTo(q('submenu'), pop, popIn, '<')
  move(`fmt-${PICKED_EXPORT}`)
  click(`fmt-${PICKED_EXPORT}`)
  tl.to(q(`fmt-${PICKED_EXPORT}`), { backgroundColor: 'var(--demo-tint-10)', duration: 0.1 }, '<')
  tl.to([q('menu'), q('submenu')], { opacity: 0, duration: 0.2 }, '+=0.15')
  tl.fromTo(
    q('toast'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.35, ease: 'power3.out', immediateRender: false },
    '<0.1',
  )
  cursorOut('+=0.4')
  final()
  wait(1.6)

  tl.set(
    [q('view-editor'), q('preview'), q('colors'), q('menu'), q('submenu'), q('toast'), q('status')],
    { opacity: 0 },
    0,
  )
  tl.set(
    [
      q('l1'),
      q('l2'),
      q('l3'),
      q('tb-pencil'),
      q(`tick-${TICKED}`),
      q(`color-check-${PICKED_COLOR}`),
    ],
    { opacity: 0 },
    0,
  )
  tl.set(
    [q('view-list'), q('edit'), q('title-ph'), q('body-ph'), q('tb-eye'), q('color-check-0')],
    { opacity: 1 },
    0,
  )
  tl.set(
    [
      q('title-text'),
      q('l0-text'),
      q('l0-pre'),
      ...TASKS.flatMap((_, index) => [q(`l${index + 1}-text`), q(`l${index + 1}-pre`)]),
    ],
    { text: '' },
    0,
  )
}

function ListView() {
  return (
    <div data-d="view-list" className="absolute inset-0 flex flex-col gap-2">
      <div className="flex items-center gap-1.5">
        <span className="flex h-7 flex-1 items-center gap-1.5 rounded-md border border-line-strong bg-canvas/80 px-2 text-[10px] text-muted">
          <SearchIcon className="size-3" /> Search notes…
        </span>
        <span
          data-d="new"
          className="flex size-7 items-center justify-center rounded-md bg-ink text-canvas"
        >
          <PlusIcon className="size-3.5" />
        </span>
        <span className="flex size-7 items-center justify-center text-muted">
          <EllipsisVerticalIcon className="size-3.5" />
        </span>
      </div>
      <div className="flex-1 space-y-1.5">
        {LIST.map((note) => (
          <div
            key={note.title}
            className={`rounded-lg border border-l-4 border-line px-2.5 py-1.5 ${note.accent} ${note.surface}`}
          >
            <span className="flex items-center gap-1.5">
              {note.pinned ? <PinIcon className="size-3 text-[var(--accent)]" /> : null}
              <span className="flex-1 truncate text-[11px] font-semibold text-ink">
                {note.title}
              </span>
              <span className="text-[9px] text-muted">{note.date}</span>
            </span>
            <span className="mt-0.5 block truncate text-[10px] text-ink-soft">{note.snippet}</span>
          </div>
        ))}
      </div>
      <p className="text-[9.5px] text-muted">{LIST.length} notes</p>
    </div>
  )
}

function EditorView() {
  return (
    <div data-d="view-editor" className="absolute inset-0 flex flex-col gap-1.5 opacity-0">
      <div className="flex items-center gap-1">
        <ArrowLeftIcon className="size-3.5 text-muted" />
        <span className="relative flex h-7 flex-1 items-center rounded-md border border-line-strong bg-canvas/80 px-2 text-[11.5px] font-medium text-ink">
          <span data-d="title-ph" className="absolute left-2 text-muted">
            Title
          </span>
          <span data-d="title-text" />
        </span>
        <PinIcon className="mx-1 size-3.5 text-muted" />
        <span data-d="palette" className="flex size-6 items-center justify-center text-muted">
          <PaletteIcon className="size-3.5" />
        </span>
        <span data-d="more" className="flex size-6 items-center justify-center text-muted">
          <EllipsisVerticalIcon className="size-3.5" />
        </span>
      </div>
      <div className="flex items-center gap-px rounded-lg border border-line bg-ink/[0.03] p-0.5">
        {TOOLBAR.map((item, index) => {
          if (item === '|') return <span key={index} className="mx-0.5 h-3.5 w-px bg-line-strong" />
          const Icon = ICONS[item]
          return (
            <span
              key={item}
              data-d={`tb-${item}`}
              className="flex size-5 items-center justify-center rounded text-ink-soft"
            >
              <Icon className="size-3" />
            </span>
          )
        })}
        <span className="ml-auto flex items-center gap-px">
          <span
            data-d="tb-preview"
            className="relative flex size-5 items-center justify-center rounded text-ink-soft"
          >
            <EyeIcon data-d="tb-eye" className="absolute size-3" />
            <PencilIcon data-d="tb-pencil" className="absolute size-3 opacity-0" />
          </span>
          <span className="flex size-5 items-center justify-center text-ink-soft">
            <SlidersHorizontalIcon className="size-3" />
          </span>
        </span>
      </div>
      <div
        data-d="surface"
        className="relative min-h-0 flex-1 rounded-lg border border-line bg-canvas/60"
      >
        <div
          data-d="edit"
          className="absolute inset-0 px-3 py-2 text-[11px] leading-[1.7] text-ink"
        >
          <span data-d="body-ph" className="absolute left-3 top-2 text-muted">
            Take a note…
          </span>
          {[0, 1, 2, 3].map((line) => (
            <span
              key={line}
              data-d={`l${line}`}
              className={`relative block h-[18.7px] ${line ? 'opacity-0' : ''}`}
            >
              {line ? (
                <span
                  data-d="sel"
                  className="absolute -inset-x-1 inset-y-0 rounded-sm bg-sky-400/25 opacity-0"
                />
              ) : null}
              <span className="relative">
                <span data-d={`l${line}-pre`} className="text-muted" />
                <span data-d={`l${line}-text`} />
              </span>
            </span>
          ))}
        </div>
        <div data-d="preview" className="absolute inset-0 px-3 py-2 text-[11px] text-ink opacity-0">
          <p className="mb-1 text-[13.5px] font-semibold">{HEADING}</p>
          <ul className="space-y-1">
            {TASKS.map((task, index) => (
              <li key={task} className="flex items-center gap-1.5">
                <span
                  data-d={`box-${index}`}
                  className="flex size-3 items-center justify-center rounded-[3px] border border-line-strong"
                >
                  <CheckIcon
                    data-d={`tick-${index}`}
                    className="size-2.5 text-canvas opacity-0"
                    strokeWidth={3}
                  />
                </span>
                <span
                  data-d={`task-${index}`}
                  className="underline-offset-0"
                  style={{
                    textDecorationLine: index === TICKED ? 'line-through' : 'none',
                    textDecorationColor: 'transparent',
                  }}
                >
                  {task}
                </span>
              </li>
            ))}
          </ul>
        </div>
      </div>
      <div
        data-d="status"
        className="flex gap-1.5 px-1 text-[9px] tabular-nums text-muted opacity-0"
      >
        <span>
          Ln {POSITION.line}, Col {POSITION.column}
        </span>
        <span>·</span>
        <span>{STATS.words} words</span>
        <span>·</span>
        <span>{STATS.characters} characters</span>
        <span>·</span>
        <span>100%</span>
        <span className="ml-auto">Saved · edited 10/24/2026, 9:00 AM</span>
      </div>
    </div>
  )
}

function Overlays() {
  return (
    <>
      <div
        data-d="colors"
        className="absolute right-6 top-8 z-10 rounded-lg border border-line-strong bg-elevated p-1.5 opacity-0 shadow-2xl"
      >
        <p className="px-0.5 pb-1 text-[9px] font-medium text-muted">Note color</p>
        <div className="grid grid-cols-4 gap-1">
          {COLORS.map((color, index) => (
            <span
              key={color.id}
              data-d={`color-${index}`}
              title={color.id}
              className="flex size-5 items-center justify-center rounded-full border border-ink/15"
              style={{ backgroundColor: color.swatch }}
            >
              <CheckIcon
                data-d={`color-check-${index}`}
                className={`size-3 ${index === 0 || index === COLORS.length - 1 ? 'text-white' : 'text-zinc-900'} ${index === 0 ? '' : 'opacity-0'}`}
              />
            </span>
          ))}
        </div>
      </div>
      <div
        data-d="menu"
        className="absolute right-0 top-8 z-10 w-40 rounded-lg border border-line-strong bg-elevated p-1 text-[10px] text-ink-soft opacity-0 shadow-2xl"
      >
        {MENU.map(({ label, Icon, hint, d }) => (
          <span
            key={label}
            data-d={d}
            className="flex items-center gap-1.5 rounded px-1.5 py-[3px]"
          >
            <Icon className="size-3 text-muted" />
            <span className="flex-1">{label}</span>
            {hint ? <span className="text-[8.5px] text-muted">{hint}</span> : null}
            {d ? <ChevronRightIcon className="size-3 text-muted" /> : null}
          </span>
        ))}
        <span className="my-1 block h-px bg-line" />
        <span className="flex items-center gap-1.5 rounded px-1.5 py-[3px] text-rose-300">
          <Trash2Icon className="size-3" /> Delete note
        </span>
      </div>
      <div
        data-d="submenu"
        className="absolute right-[164px] top-8 z-10 w-36 rounded-lg border border-line-strong bg-elevated p-1 text-[10px] text-ink-soft opacity-0 shadow-2xl"
      >
        {EXPORTS.map((label, index) => (
          <span key={label} data-d={`fmt-${index}`} className="block rounded px-1.5 py-[3px]">
            {label}
          </span>
        ))}
      </div>
      <div
        data-d="toast"
        className="absolute bottom-0 right-0 z-10 w-56 rounded-lg border border-line-strong bg-elevated p-2 opacity-0 shadow-2xl"
      >
        <p className="flex items-center gap-1.5 text-[10px] font-semibold text-ink">
          <DownloadIcon className="size-3 text-[var(--accent)]" /> {FILE}
        </p>
        <pre className="mt-1 whitespace-pre-wrap rounded bg-ink/[0.04] p-1.5 font-mono text-[8.5px] leading-snug text-ink-soft">
          {MARKDOWN}
        </pre>
      </div>
    </>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`Notes creating "${TITLE}", turning lines into a heading and a checklist, ticking one off in preview, colouring it yellow and exporting it as Markdown`}
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="relative h-full">
          <ListView />
          <EditorView />
          <Overlays />
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
